const input = $json;

const route = input.route || 'routine';

const statusByRoute = {
  routine: 'acknowledged',
  manager_approval: 'pending_approval',
  human_escalation: 'escalated'
};

const status = statusByRoute[route] || 'received';

// 验证审计记录必须具备的业务字段
if (!input.eventId) {
  throw new Error('Missing eventId');
}

if (!input.chatId) {
  throw new Error('Missing chatId');
}

if (!input.text) {
  throw new Error('Missing employee message');
}

// 标准化 RAG 审计数值
const retrievalCount = Number(input.retrievalCount);

const retrievalTopScore =
  typeof input.retrievalTopScore === 'number' &&
  Number.isFinite(input.retrievalTopScore)
    ? input.retrievalTopScore
    : null;

// 输出字段名与 Supabase 表字段保持一致
return {
  event_id: input.eventId,
  message_id: input.messageId || null,
  chat_id: input.chatId,
  sender_open_id: input.senderOpenId || null,
  employee_message: input.text,

  category: input.category || 'Other',
  priority: input.priority || 'Normal',
  summary: input.summary || null,
  suggested_reply: input.suggestedReply || null,

  route: route,
  requires_approval: input.requiresApproval === true,
  needs_human_escalation:
    input.needsHumanEscalation === true,

  status: status,

  rag_grounded: input.ragGrounded === true,
  sop_source: input.sopSource || null,
  sop_version: input.sopVersion || null,
  retrieval_count: Number.isFinite(retrievalCount)
    ? Math.max(0, Math.trunc(retrievalCount))
    : 0,
  retrieval_top_score: retrievalTopScore
};
